export const SPELLS = [
    // ---- fight
    { cat: 'fight', name: 'Инферно', say: 'рука к лицу + «Инферно»', desc: 'Скажите «Инферно» и поднесите руку к лицу — из ладони пойдёт поток огня, который следует за движением руки. Им удобно жечь врагов, зомби и живые деревья, поджигать сухое и греться у огня или жарить еду. Огонь горит до 5 секунд, пока вы его держите: тратит по 3 в секунду. Щит Protection, вода и стена его останавливают. «Стоп» гасит пламя.', dmg: '1/тик', cost: '10 + 3/с', icon: 'assets/icons/inferno.svg' },
    { cat: 'fight', name: 'Тандервейв', say: 'рука к лицу + «Тандервейв» / «Гром»', desc: 'Скажите «Тандервейв» или «Гром» — и с неба ударит веер молний перед вами. Поможет разом поразить толпу: зомби, жителей, рыцарей, животных, каждому в зоне по 10 урона. Удар идёт сверху, поэтому обычный щит Protection и обычная броня не спасают; от Protection Maxima, щита богов и магической брони защищают. Ближних сбивает с ног, дальних отшатывает. Сквозь стены и горы не бьёт. Платите один раз.', dmg: '10 каждому в зоне', cost: 40, icon: 'assets/icons/thunderwave.svg' },
    { cat: 'duel', name: 'Даст', say: 'направить поднятую руку на цель + «Даст» / «Санд» (достаёт до 30 м; дальше — подсказка «Слишком далеко», мана цела)', desc: 'Скажите «Даст» или «Санд», направив руку на цель до 30 м. Песчаный заряд замедляет: песок летит в глаза и суставы, и 5 секунд цель двигается намного медленнее — зверь, зомби, житель или другой игрок. Отбить можно щитом или встречным заклинанием.', dmg: 'замедление 5 с', cost: 8, icon: 'assets/icons/dust.svg' },
    { cat: 'fight', name: 'Бомбардо', say: 'рука к лицу + «Бомбардо»', desc: 'Скажите «Бомбардо» — из руки полетит взрывной шар. Он рвёт горы и землю, ломает деревья и разбрасывает зомби, людей, животных и предметы, а рядом всё сбивает с ног. Помогает пробить стену или убрать препятствие. Взрывается в кроне дерева, а не пролетает сквозь листву. Рядом с собой не взрывайте: ранит и вас.', max: 'Максима: «Бомбардо Максима» (красная лента) в 3 раза мощнее — огромная волна из руки и широкая воронка, урон до 24, стоит 25 маны.', dmg: 'до 8', cost: 15, icon: 'assets/icons/bombardo.svg' },
    { cat: 'fight', name: 'Earthquake', say: 'обе руки в сторону удара, поднять ногу и топнуть + «Earthquake» (слышится и как «Escape»)', desc: 'Вытяните обе руки в сторону удара, поднимите ногу, топните и скажите «Earthquake» («Escape»). Поможет сбить врагов с ног и разогнать толпу: трещина проваливается, и всё на её пути падает навзничь и получает урон. Существа встают сами, игроку нужно присесть и выпрямиться.', max: 'Максима: «Earthquake Максима» (стоит 25 маны) — три трещины сразу, длиннее (до 32 м) и шире, урон 12, и лежат дольше.', dmg: '4', cost: 10, icon: 'assets/icons/earthquake.svg' },
    { cat: 'fight', name: 'Wind', say: 'поднять руку в нужную сторону + «Wind» или «Вайнд» (одно и то же; «Wind Maxima» / «Вайнд Максима» — сильнее)', desc: 'Поднимите руку в нужную сторону и скажите «Wind» или «Вайнд». Порыв ветра поможет отбросить врагов и сбить их с ног: зомби, людей, рыцарей, животных и игроков отшвыривает на несколько метров, предметы сдувает. Не ранит. На корабле ветер надувает паруса и гонит его вперёд, пока есть мана (тратится 1 в секунду) или пока не скажете «стоп».', max: 'Максима: «Вайнд Максима» (20 маны) в 3 раза сильнее и дальше, до 24 м; поднятая палочка даёт кольцо ветра вокруг вас, которое гасит весь огонь рядом, включая ваш адский огонь. Щит: купол «Protection Maxima» не пропускает даже воздух, а за обычным «Protection» устоит только тот, чья устойчивость выше 78.', dmg: '—', cost: 8, icon: 'assets/icons/wind.svg' },
    { cat: 'fight', name: 'Overgrown', say: 'направить поднятую руку на одного или на толпу + «Overgrown» («Овергроун», «Оверграун»)', desc: 'Направьте поднятую руку на одного или на толпу и скажите «Overgrown» («Овергроун», «Оверграун»). Поможет разогнать врагов и подбросить их вверх: зомби, людей, рыцарей, животных и игроков разбрасывает в стороны от линии заклинания. Само по себе не ранит, но тот, кого сбросит с обрыва или стены, пострадает от падения.', max: 'Максима: «Overgrown Максима» (салатовая лента) в 2 раза сильнее — дальше и выше, до 24 м; стоит 20 маны.', dmg: '—', cost: 10, icon: 'assets/icons/overgrown.svg' },
    { cat: 'fight', name: 'Wind Impulse', say: 'поднять палочку (руку) вверх + «Wind Impulse» («Вайнд Импульс»)', desc: 'Поднимите палочку или руку вверх и скажите «Wind Impulse» («Вайнд Импульс»). Из вас расходится кольцо воздуха, которое отгоняет всех вокруг: людей, зомби, животных, моряков и игроков в трёх метрах отталкивает от вас, ближних сбивает с ног. Лёгкие вещи разлетаются, книги-птицы падают. Само не ранит. ', max: 'Максима: «Wind Impulse Максима» отталкивает на 9 метров и стоит 40 маны.', dmg: '—', cost: 10, icon: 'assets/icons/wind_impulse.svg' },
    { cat: 'fight', name: 'Drawdown', say: 'направить палочку (руку) на землю + «Drawdown» («Дравдаун»)', desc: 'Направьте палочку или руку на землю и скажите «Drawdown» («Дравдаун»). Поможет опустить землю под врагом или убрать холм: земля проседает в чашу, яма углубляется, пока палочка стоит на месте (до 6 блоков), и тянется за ней, если вести по земле. Всё на земле опускается вместе с ней: дома, стены, деревья, сундуки, люди и звери. Продолжается, пока не скажете «стоп» или не кончится мана: тратит по 1 в секунду. Вода, коренная порода и дом под защитой не проседают. Проседающий замок пугает жителей и злит стражу.', max: 'Максима: «Drawdown Максима» — чаша шире (радиус 7 м) и глубже (до 9 блоков); тратит по 2 в секунду.', dmg: '—', cost: 5, icon: 'assets/icons/drawdown.svg' },
    { cat: 'fight', name: 'Liquidation', say: 'направить палочку (руку) на вещь или на того, кто что-то держит + «Liquidation» («Ликвидейшн»)', desc: 'Liquidation позволяет избавиться от ненужной вещи — или отнять оружие у врага. Чтобы убрать вещь, направьте палочку или руку на неё и скажите «Liquidation» («Ликвидейшн»): серо-сиреневый всплеск рассыплет её в прах. Еда, меч, щит, блок стены или доска рассыпаются сразу. Волшебные вещи (палочка, свиток, книга, зелье, камень башни) и большие (котёл, сундук, кровать, дверь) обычный всплеск не берёт. Кристалл маны раскалывается, и его сила идёт к вам. Дары богов не берёт ничто. Чтобы отнять оружие, направьте руку на человека, зверя-великана или скелета и скажите то же слово: заряд летит как в дуэли — встречные заряды сталкиваются, а «Protection» его останавливает. Если заряд попал, рассыплется вещь в руке — сначала в основной руке, а если там пусто, то в другой (меч, топор, пистолет, щит). Обычный «Liquidation» берёт только немагическое: меч рыцаря и саблю скелета — да, палочку волшебника и меч короля — нет. Без оружия скелет и рыцарь бьют кулаками. Цель, в которую попал заряд, получает 3 урона.', max: 'Максима: «Liquidation Максима» (стоит 25 маны) рассыпает и волшебное — палочку, меч короля, даже шпагу капитана Чёрные Усы, — прямо в руках, и большие вещи: котёл, сундук, кровать, дверь. Проигравший дуэль «Liquidation Максима» теряет палочку: она рассыплется, и придётся искать другую. Дары богов и палочку, выигранную на арене, не берёт и она.', dmg: '3', cost: 10, icon: 'assets/icons/liquidation.svg' },
    { cat: 'fight', name: 'Lightning Strike', say: 'обе руки вверх + «Lightning Strike»', desc: 'Поднимите обе руки вверх и скажите «Lightning Strike». Через пять секунд небо потемнеет, и молния упадёт вам в руки. Помогает поразить цель на расстоянии: плавно наведите руку и задержите её на цели — молния ударит туда. Не успели навести — ударит в вас. Наносит 20 урона, кто выжил, падает с ног.', dmg: '20', cost: 25, icon: 'assets/icons/lightning_strike.svg' },
    { cat: 'fight', name: 'Total Destruction', say: 'направить поднятую руку на замок, дом или место + «Total Destruction» («Тотал Дестракшн»)', desc: 'Поднимите руку на замок, дом или место и скажите «Total Destruction» («Тотал Дестракшн»). Это самое разрушительное заклинание, в 5 раз сильнее «Бомбардо Максима». Помогает сровнять с землёй крепость, башню или деревню: в круге около 20 м земля трясётся, и через 3 секунды всё построенное — замки, дома, стены, башни, деревья — рассыпается в руины. Пещеры под этим местом обваливаются. Все существа там падают и сильно ранены. Нужен максимум маны 100 и больше, стоит 80 маны. ', max: 'Максима: «Total Destruction Максима» в 2 раза сильнее — круг около 28 м, урон вдвое больше; нужен максимум маны 200, стоит 160 маны, учится из того же свитка.', dmg: 'до 120', cost: 80, icon: 'assets/icons/total_destruction.svg' },
    { cat: 'fight', name: 'Circle Attack', say: 'развести руки в стороны, как буква T (как для «Protection Maxima»), + «Circle Attack» («Сёркл Аттак»; сильнее — «Circle Attack Maxima» / «Сёркл Аттак Максима»)', desc: 'Разведите руки в стороны, как буква T, и скажите «Circle Attack» («Сёркл Аттак»). Поможет разом отбросить всех вокруг: от волшебника на 30 м во все стороны катится золотая волна света. Она сбивает с ног и отбрасывает, и урон сильнее вблизи: 30 у самого волшебника, 10 на краю. Земля и дома под волной рушатся вслед за ней, поэтому дальние успевают спрятаться. Лучи бьют 3–5 случайных существ по 10. Сам волшебник на своём островке волна не трогает. Нужен максимум маны 100, стоит 80 маны. Звучит своя музыка.', max: 'Максима: «Circle Attack Maxima» — круг 45 м, урон до 45, лучей больше, отбрасывает в полтора раза дальше; нужен максимум маны 200, стоит 160 маны.', dmg: '30 / 20 / 10 + лучи 10', cost: 80, icon: 'assets/icons/circle_attack.svg' },
    { cat: 'fight', name: 'Inspirius', say: 'палочка в руке + «Inspirius» («Инспириус»)', desc: 'Направьте всю силу в палочку и скажите «Inspirius» («Инспириус»). Из палочки вылетит живой электрический шар света: он летит около 5 секунд туда, куда смотрит палочка, и им можно рулить. Поможет пробить любую крепость: коснувшись чего угодно, шар взрывается огромной ямой и ударной волной, и всё построенное в радиусе 45 м рушится. Урон до 20 м — 100, до 40 м — 50, до 60 м — 25, всех сбивает с ног.', dmg: '100 / 50 / 25', cost: 500, icon: 'assets/icons/inspirius.svg' },
    { cat: 'dark', name: 'Let the Hellfire Come', say: 'палочка в руке + «Let the Hellfire Come» («лет зе хеллфаер кам»; можно «Hellfire come», «Come, hellfire»)', desc: 'Скажите «Let the Hellfire Come» — из палочки вырвется огромная масса живого огня. Это самое сильное огненное заклинание, им можно выжечь целую армию или лес. Огонь плывёт за палочкой: согнутая рука — он близко, вытянутая — до 18 м, разведённые руки — больше. Сжигает всех, до кого дотянется, жар обжигает и тех, кто рядом, даже в доспехах. Жители и животные бегут, огонь перекидывается на деревья и траву. Крутите рукой по кругу — огонь уходит в кольцо вокруг вас, стена пламени около 40 м. Не входите в огонь и не направляйте его на себя: сгорите. Щит Protection лишь ослабляет жар, вода гасит огонь. Пока держите, тратит ещё по 2 в секунду. «Стоп» останавливает его в любой момент и бесплатно; погасший огонь распадается на костры, которые горят ещё полминуты. Первый настоящий поджог даёт +20 к максимуму маны (один раз). Это чёрная магия: сам каст тьму не добавляет, но каждый человекоподобный (волшебник, рыцарь, житель, моряк, игрок, Ледяная Королева), которого убил этот огонь, даёт +1 к уровню чёрной магии; за животных, зомби, скелетов и драконов — ничего.', dmg: '4 каждые 0,25 с в огне, жар рядом — до 2', cost: '80 + 2/с, «стоп» 50', icon: 'assets/icons/hellfire.svg' },
    { cat: 'fight', name: 'Брейнрот', say: 'посмотреть на существо + «Брейнрот»', desc: 'Посмотрите на существо и скажите «Брейнрот» — оно станет вашим слугой на 45 секунд. Слуга ходит за вами, защищает и бьёт врагов; «Атак» пошлёт его на того, на кого вы показали. Подействует на зомби, коров, лошадей и чужие живые деревья. На человекоподобных — жителей, рыцарей и волшебников — не действует.', dmg: '—', cost: 15, icon: 'assets/icons/brainrot.svg' },
    { cat: 'fight', name: 'Брейнрот Максима', say: 'посмотреть на дракона + «Брейнрот Максима»', desc: 'Посмотрите на дракона и скажите «Брейнрот Максима» — он перестанет злиться и подпустит. Тогда можно сесть ему на спину: шаг на месте — он идёт, руки вверх — взлетает, присесть на земле — слезть. Не станет послушным и не пойдёт в атаку по приказу. Держится, пока платите 0,5 маны в секунду; «стоп», конец маны или вы далеко от дракона — он садится. Не берёт дракона, который уже зол на вас, обижен или обокраден вами. Удар по дракону под заклинанием его рвёт. Если он зол на кого-то другого, скажите «Атак» на того — дракон нападёт только на него.', dmg: '—', cost: 30, icon: 'assets/icons/brainrot_maxima.svg' },
    { cat: 'dark', name: 'Империус', say: 'направить руку (палочку) на существо или посмотреть на него, не дальше 90 м, + «Империус» («Imperius»)', desc: 'Направьте руку или палочку на существо в 30 м и скажите «Империус» («Imperius»). Ваше сознание переходит в него: вы управляете им, а ваше тело стоит на месте с белыми горящими глазами. Поможет подчинить зомби, жителей, рыцарей, торговцев, волшебников, моряков, коров, баранов, коней и свиней: они будут ходить, прыгать, бить и бежать по вашей воле. Сквозь стены и заборы он не пройдёт, в глубокую воду не полезет. Боссов и магических существ не берёт, игроков — только «Империус Максима». «Стоп» возвращает сознание в тело. Связь рвётся, если кончилась мана или существо погибло: тогда вы возвращаетесь в своё тело невредимым. Пока вы в существе, тело видят все и могут найти. Чёрная магия: каждое заклинание даёт 50% шанс +1 к тьме (см. «Механика игры → Чёрная магия»).', dmg: 'удар самого существа', cost: '100 + 1/с', icon: 'assets/icons/imperius.svg' },
    { cat: 'dark', name: 'Give Me My Power', say: 'поднять руку (палочку) и направить на свой скелет + «Give Me My Power» («Гив ми май пауэр», «Верни мне мою силу»)', desc: 'Поднимите руку или палочку на свой скелет, над которым золотые искры, и скажите «Give Me My Power» («Верни мне мою силу»). Вернётся сила, оставшаяся в теле: ячейки маны, свитки, выученные заклинания, полёт, ачивки. Набранное после смерти пропадёт: сила заменяется, а не складывается. Действует только на ваш скелет.  Чёрная магия: каждый каст — с шансом 50% +1 к тьме (см. «Механика игры → Чёрная магия»); волшебники её презирают.', cost: 50, icon: 'assets/icons/my_power.svg' },
    { cat: 'move', name: 'Snowman', say: 'направить поднятую руку (палочку) на снег + «Snowman» («Сноумен», «Снеговик»)', desc: 'Направьте поднятую руку или палочку на снег и скажите «Snowman» («Сноумен», «Снеговик»). Снег сам собирается в доброго снеговика, который оживает и моргает. Поможет украсить зимний лагерь и обзавестись спутником: он никого не атакует и не слушается приказов, а просто бродит рядом и смотрит на тех, кто рядом. Боится огня: от костра и взрывов убегает, а сильный огонь растапливает его. У него 10 здоровья: удары и простые заклинания его рассыпают. Холод ему не страшен, злые снеговики и Ледяная Королева его не трогают. Работает только на снегу.', dmg: '—', cost: 30, icon: 'assets/icons/snowman.svg' },
    { cat: 'dark', name: 'Alive', say: 'направить поднятую руку на дерево или могилу + «Alive» («Алайв»)', desc: 'Направьте поднятую руку на дерево или могилу и скажите «Alive» («Алайв»). Дерево оживёт за три секунды, а из могилы встанет скелет. Поможет получить слугу: он ходит за вами, охраняет и бьёт врагов, а «Атак» пошлёт его на того, на кого вы покажете. Живёт, пока есть мана (тратится 0,5 в секунду). Кончилась мана, вы ушли дальше 50 м или сказали «стоп» — дерево падает бревном, его можно собрать «Gather», а скелет рассыпается на кости. Огонь, молния и «Бомбардо» уничтожают живое дерево; «Авада Кедавра» скелет не берёт, но он рассыпается от огня, взрывов и ударов по костям. Золотые деревья не оживают. Чёрная магия: каждый каст — с шансом 50% +1 к тьме (см. «Механика игры → Чёрная магия»); волшебники её презирают.', dmg: 'ветки −4', cost: 25, icon: 'assets/icons/alive.svg' },
    { cat: 'dark', name: 'Alive Максима', say: 'направить поднятую руку на дерево или могилу + «Alive Максима»', desc: 'Оживляет всё вокруг сразу: на кладбище встают все мертвецы из неразрытых могил, а в лесу оживает дерево, на которое вы показали, и деревья рядом с ним (в радиусе 14 м, до 6 штук). Поможет собрать целую армию слуг. Каждый тратит 1 ману в секунду, поэтому сколько ожило — столько маны и уходит. Кончилась мана, «стоп», вы ушли дальше 50 м или вас оглушили или убили — все разом рассыпаются или падают. Чёрная магия: каждый каст — с шансом 50% +1 к тьме (см. «Механика игры → Чёрная магия»); волшебники её презирают.', dmg: 'как у «Alive»', cost: 50, icon: 'assets/icons/alive_max.svg' },
    // ---- duel
    { cat: 'duel', name: 'Айс / Frozen', say: 'направить поднятую руку на цель + «Айс» (или «Frozen», «Лёд» — это одно и то же заклинание); с водяным шаром — «Frozen» замораживает воду (достаёт до 30 м; дальше — подсказка «Слишком далеко», мана цела)', desc: 'Направьте поднятую руку на цель и скажите «Айс», «Frozen» или «Лёд». Ледяной кристалл по морозному лучу замораживает живое: цель целиком во льду 10 секунд и теряет 3 здоровья в секунду. Поможет надолго остановить врага: зомби, жителей, рыцарей, зверей и игроков. Мастер башни волшебников отбивает лёд, капитан Чёрные Усы — саблей; Ледяная Королева и всё ледяное холода не боится. Дракона и паучиху обычным «Айсом» не заморозить, для них нужна Максима. В режиме выживания удар по замороженному игроку смертелен. Заряд можно отбить щитом или встречным заклинанием. Работает только на отдельно сказанное слово. С водяным шаром замораживает и его.', max: 'Максима: «Айс Максима» (20 маны) — 10 секунд по 10 здоровья в секунду, бьёт в ту часть тела, куда показывает рука. Против дракона и паучихи: в морду — не могут атаковать, в лапу — хромают, в туловище — замедляются. Побеждать их помогут «Бомбардо», потом «Айс Максима», потом «Электром» или «Пилбидрио».', dmg: '3/с 10 с', cost: 5, icon: 'assets/icons/ice.svg' },
    { cat: 'duel', name: 'Сапира', say: 'направить поднятую руку на цель + «Сапира» (достаёт до 30 м; дальше — подсказка «Слишком далеко», мана цела)', desc: 'Направьте руку на цель и скажите «Сапира» — заряд достанет до 30 м. Медленный тяжёлый фиолетовый сгусток сбивает с ног и наносит 10 урона. Отбить можно щитом или встречным заклинанием.', dmg: '10', cost: 20, icon: 'assets/icons/sapira.svg' },
    { cat: 'duel', name: 'Остолбеней', say: 'направить поднятую руку + «Остолбеней» (достаёт до 30 м; дальше — подсказка «Слишком далеко», мана цела)', desc: 'Скажите «Остолбеней» в сторону цели до 30 м. Оглушающий красный заряд: попавший падает навзничь и пятнадцать секунд не двигается, что даёт время на бой. Заряд хорошо виден остальным игрокам. Существа встают сами, игрок — присев и выпрямившись.', dmg: 'оглушение 15 с', cost: 12, icon: 'assets/icons/stupefy.svg' },
    { cat: 'duel', name: 'Экспеллиармус', say: 'направить поднятую руку на волшебника + «Экспеллиармус» (достаёт до 30 м; дальше — подсказка «Слишком далеко», мана цела)', desc: 'Направьте поднятую руку на волшебника и скажите «Экспеллиармус» — заряд достанет до 30 м. Помогает обезоружить: попав в волшебника с палочкой, он вырывает её, и палочка падает в 4–10 метрах в случайную сторону, её может подобрать и кто угодно, в том числе вы. Без палочки колдовать можно, но слабее. У рыцаря вылетает меч, и он дерётся кулаками. Так же можно обезоружить капитана Чёрные Усы и скелетов его корабля: шпага или сабля вылетает на палубу, а безоружный капитан не отбивает ваши заряды, бьёт слабее — самое время атаковать. Но он пойдёт за шпагой и потянется за ней несколько секунд: успейте ударить или подобрать её первым (шпагу, оставшуюся на палубе, он потеряет насовсем, если вы её взяли). Зомби и зверей только толкает; на живое дерево и паучиху не действует. Ледяной Жезл Королевы не выбить — это дар богов. Заряд можно отбить щитом или встречным заклинанием: тогда будет дуэль, и проигравший достаётся победителю вместе с его заклинанием.', dmg: 'выбивает палочку / меч', cost: 12, icon: 'assets/icons/expelliarmus.svg' },
    { cat: 'duel', name: 'Disarmor', say: 'направить поднятую руку на того, кто в латах + «Disarmor» («дизармор»; можно «раздеть»); чтобы снять с себя — поднять палочку (руку) вверх, к небу, + «Disarmor»', desc: 'Направьте руку на рыцаря или короля и скажите «Disarmor» («дизармор», «раздеть»). Заряд сбивает металлические доспехи — шлем, нагрудник, поножи. Детали разлетаются: их можно подобрать или надеть, а рыцарь дерётся дальше без брони. С волшебника слетает обычная мантия, с игрока — обычные доспехи и мантия. Волшебные доспехи, мантию и костюм Высшего мага не снять. Задетого отбрасывает с кувырком и роняет; зомби, зверей и моряков только отталкивает. Чтобы снять латы с себя, поднимите палочку вверх и скажите слово: обычные доспехи упадут рядом.', dmg: 'снимает обычные латы', cost: 12, icon: 'assets/icons/disarmor.svg' },
    { cat: 'duel', name: 'Джолт', say: 'направить поднятую руку на цель + «Джолт»', desc: 'Направьте поднятую руку на цель и скажите «Джолт». Почти невидимый сгусток воздуха отбрасывает цель далеко назад, поэтому его удобно использовать, чтобы отшвырнуть врага или сбросить с обрыва. Попавший кувыркается в воздухе, падает и несколько секунд лежит. Существа встают сами, а игроку нужно присесть и выпрямиться. После удара у игрока кружится голова: картинка плывёт, при ходьбе шатает; существа спотыкаются, а волшебники мажут. Само заклинание не ранит, но падение с обрыва, стены или борта корабля — больно. Тяжёлых (рыцаря, корову, лошадь) отбрасывает ближе. Лежащие на пути вещи отлетают. Можно отбить щитом или встречным заклинанием.', dmg: 'толчок, падение', cost: 5, icon: 'assets/icons/jolt.svg' },
    { cat: 'duel', name: 'Джолт Максима', say: 'направить поднятую руку на цель + «Джолт Максима»', desc: 'Скажите «Джолт Максима» — сильный толчок. Помогает отбросить опасного врага далеко и высоко: цель делает в воздухе пару кувырков, дольше лежит и дольше приходит в себя.', dmg: 'сильный толчок, падение', cost: 15, icon: 'assets/icons/jolt_max.svg' },
    { cat: 'dark', name: 'Авада Кедавра', say: 'направить поднятую руку + «Авада Кедавра» (достаёт до 30 м; дальше — подсказка «Слишком далеко», мана цела)', desc: 'Направьте руку на цель и скажите «Авада Кедавра» — зелёный заряд достанет до 30 м и сразу снимет 25 здоровья. Пригодится в дуэли против сильного противника. Чёрная магия: каждый каст — с шансом 50% +1 к тьме (см. «Механика игры → Чёрная магия»); волшебники её презирают.', dmg: '25', cost: 25, icon: 'assets/icons/avada.svg' },
    // the strong duel spells (StrongSpells.js): the same flying charge — another light, another sound, another harm
    { cat: 'dark', name: 'Акцентрик', say: 'направить поднятую руку (палочку) на цель + «Акцентрик» («Accentric») (достаёт до 30 м; дальше — подсказка «Слишком далеко», мана цела)', desc: 'Направьте палочку на цель и скажите «Акцентрик» — сиреневый заряд достанет до 30 м. Помогает ослабить противника: игрок минуту видит всё мутно и плывёт, но двигаться и колдовать может, и теряет 5 здоровья в секунду, всего 40. Существа — жители, рыцари, волшебники, звери, драконы — минуту растеряны, их удары попадают вдвое реже. На деревья и скелетов не действует. Снаружи ломает защиту дома, снимая 40 силы. Чёрная магия: каждый каст — с шансом 50% +1 к тьме (см. «Механика игры → Чёрная магия»); волшебники её презирают.', dmg: '5/с, всего 40', cost: 50, icon: 'assets/icons/accentric.svg' },
    { cat: 'duel', name: 'Пилбидрио', say: 'направить поднятую руку (палочку) на цель + «Пилбидрио» (достаёт до 75 м; дальше — подсказка «Слишком далеко», мана цела)', desc: 'Направьте палочку на цель и скажите «Пилбидрио» — луч бело-золотого света достанет до 75 м. Это сильнейший удар по одной цели: он снимает 80 здоровья, а цель с 80 здоровья и меньше разрывает на части, будь то зомби или дракон. Игрока разрывает до скелета, а вещи падают рядом. Снаружи ломает защиту дома, снимая 80 из 100 силы.', dmg: '80 (≤ 80 — разрывает)', cost: 100, icon: 'assets/icons/pilbidrio.svg' },
    { cat: 'duel', name: 'Электром', say: 'направить поднятую руку (палочку) на цель + «Электром» («Electrum»), держать руку на цели; «стоп» — отпустить (достаёт до 60 м; дальше — подсказка «Слишком далеко», мана цела)', desc: 'Направьте руку или палочку на цель, скажите «Электром» («Electrum») и держите руку на цели, пока не скажете «стоп». Поможет удержать опасного врага: настоящая молния бьёт в цель и тянется за рукой — сначала 25 урона, потом по 20 в секунду, пока держите. Бьёт любое существо, даже дракона. Пока держите луч, другие заклинания не работают. Молния обрывается, если вас сбили с ног, оглушили, заморозили или выбили палочку, а также если рука ушла с цели. Щит Protection впитывает молнию своей маной. Снаружи ломает защиту дома: за 12 секунд она трескается и рассыпается. Пока держите, тратит по 3 в секунду.', dmg: '25, потом 20/с', cost: '50 + 3/с', icon: 'assets/icons/electrum.svg' },
    { cat: 'gods', name: 'Дай', say: 'поднять руку (палочку), навести прямо на цель и сказать одно слово «Дай» («Die», «Дия») — отдельно, без других слов', desc: 'Поднимите руку или палочку, наведите на цель и скажите одно слово «Дай» отдельно, без других слов. Это божественное заклинание: оно мгновенно убивает любое существо, сколько бы у него ни было здоровья — дракона, Ледяную Королеву, капитана Чёрные Усы, паучиху, короля. Пробивает любую защиту, даже щит богов и костюм Высшего мага. Божественная защита после первого удара только разбивается. Цель испепеляется, не оставляя ни тела, ни вещей; дары богов падают на землю. Игрок, убитый «Даем», свою прежнюю силу не вернёт: тела нет. Достаёт до 50 м. Учится только в библиотеке храма богов на Венере (чёрная лента); первое использование даёт +100 ячеек маны. В дуэли тратит ещё 10 в секунду. Срабатывает только на отдельное слово, не из разговора.', dmg: 'смерть', cost: '1000 (+10/с в дуэли)', icon: 'assets/icons/die.svg' },
    { cat: 'duel', name: 'Максима в дуэли', say: 'пока заряды давят друг на друга, крикните «Максима»', desc: 'Скажите «Максима» во время дуэли, пока заряды давят друг на друга: точка встречи лучей сдвигается к сопернику. Каждый крик добавляет 5%, повторять можно не чаще раза в три секунды. Пока идёт дуэль, каждый теряет по 1 мане в секунду.', dmg: '—', cost: 5, icon: 'assets/icons/duel_maxima.svg' },
    // ---- guard
    { cat: 'guard', name: 'Suit Up', say: '«Suit Up» («сьют ап»; можно «одеть всё»)', desc: 'Скажите «Suit Up» («сьют ап») — и вы сами наденете лучший комплект: шлем, нагрудник, поножи и мантию из ваших ячеек и вещей, которые лежат рядом. Пригодится, когда надо быстро одеться, например после победы над рыцарем или волшебником. Надетое раньше уходит в ячейку. Заклинание можно заменить жестом: возьмите вещь в руку и приложите к голове, груди или бедру. ', dmg: '—', cost: 5, icon: 'assets/icons/suit_up.svg' },
    { cat: 'guard', name: 'Protection', say: 'вытянуть руку (палочку) + «Protection» — или скрестить руки перед грудью', desc: 'Это простейшее заклинание: его волшебник может творить без палочки, голой рукой (все остальные заклинания без палочки пока не получатся — подробности в разделе «Пентаграммы»). Вытяните руку с палочкой и скажите «Protection» — перед вами встанет голубой щит. Можно и без слов: встаньте прямо и скрестите руки перед грудью, как будто защищаетесь, — щит встанет прямо перед скрещёнными руками (чуть впереди вас) и будет стоять, пока руки скрещены; разведёте руки — он пропадёт. Это заклинание позволяет защититься от большинства заклинаний и стрел: они отскакивают, а взрыв рядом ранит вполовину. Держите щит рукой без палочки: заклинание палочкой в той же руке его собьёт. Держится, пока есть мана (тратится 0,5 в секунду); каждое остановленное заклинание снимает половину своей цены. «Стоп» или резкий взмах убирает щит. ', dmg: '—', cost: 5, icon: 'assets/icons/shield.svg' },
    { cat: 'guard', name: 'Protection Maxima', say: 'руки в стороны буквой «T» + «Protection Maxima»', desc: 'Разведите руки в стороны буквой T и скажите «Protection Maxima» — вокруг всего тела встанет голубой шар. Это самая надёжная защита: он отражает заклинания со всех сторон и полностью спасает от взрывов, своих и чужих. Держится, пока не скажете «стоп» или не кончится мана (1 в секунду); стоит 20 маны сразу. Каждое остановленное заклинание снимает половину своей цены, а если маны не хватит — шар разобьётся. Палочкой можно колдовать дальше, шар не пропадёт.', dmg: '—', cost: 20, icon: 'assets/icons/shield_max.svg' },
    { cat: 'guard', name: 'Groundprud', say: 'направить палочку (руку) вниз-вперёд на землю на расстоянии до 18 м + «Groundprud» («граунтпруд», «граунд пруд») — одним словом; «граунд» или «пруд» отдельно не сработают', desc: 'Направьте палочку или руку вниз-вперёд на землю и скажите «Groundprud» одним словом. Помогает быстро загородиться от врагов и заклинаний: из-под земли за секунду вырастает стена 7 блоков в ширину и 6 в высоту. Она состоит из того, что под ней, — камня, песка, земли с травой. Не работает на заколдованном камне, на даре богов, на воде, в космосе и внутри чужой защиты. Стена — обычные блоки, их можно разобрать «Бомбардо», «Gather» или киркой. Если на месте стены кто-то стоит, блок его пропускает. Первое срабатывание даёт +2 ячейки маны.', dmg: '—', cost: 10, icon: 'assets/icons/groundprud.svg' },
    { cat: 'guard', name: 'Nihilis Atra', say: 'палочка в руке, направить туда, где чёрная магия, + «Nihilis Atra» («нихилис атра» — оба слова вместе; одно слово не сработает)', desc: 'Nihilis Atra рассеивает чёрную магию: из палочки идёт широкий конус белого света (как ветер у «Вайнд» — не на одну цель, а на всё, что в конусе, до 28 м). Всё, что живёт чёрной магией, рассыпается на части: ожившие деревья («Alive» и «Alive Максима»), поднятые на кладбищах мертвецы, скелеты экипажа чёрного корабля, адские горгульи, форма страшного монстра (человек в ней жив), «Империус» (разум возвращается в тело). Чёрные пентаграммы в конусе гаснут. Чёрные маги от света не рассыпаются, но он их очень ранит: чёрный маг уровня 60 и выше теряет больше половины здоровья и боится этого заклинания — убегает; у кого тьмы меньше — рана полегче. Купол «Protection Maxima» чёрного мага свет разбивает; у обычных магов защиту не трогает. Капитан Чёрные Усы проклят — получает тяжёлую рану, но не умирает. Обычных людей, животных, зомби, драконов и всё остальное не трогает. Срабатывает сразу. Выучить можно только со свитка.', dmg: 'чёрный маг 60+: 55% здоровья; ниже: 20%', cost: 40, icon: 'assets/icons/nihilis.svg' },
    { cat: 'guard', name: 'Ground Vortex', say: 'палочка в руке, показать ею НА землю (до 16 м) + «Ground Vortex» («граунд вортекс» — оба слова вместе); «Атака» — бросить, «Shield» — заслон, «стоп» — отпустить', desc: 'Ground Vortex поднимает землю, камень, дерево — любые блоки — в воздух и превращает их в оружие и щит. Как пользоваться: покажите палочкой на землю (или стену, или дерево) и скажите «Ground Vortex». Пока палочка смотрит на блоки, они поднимаются и просто висят облаком над этим местом, плавно покачиваясь, и идут за палочкой. Чтобы закрутить их в воронку вокруг себя, водите рукой кругами: чем больше кругов, тем больше блоков (до 160). Перестали кружить и повели палочку в одну сторону — блоки потянутся за ней змеёй. Чтобы бросить блоки, скажите «Атака» (или резко бросьте рукой): они полетят туда, куда показывает палочка, и ранят и толкают всех, кого заденут. Если поднять палочку полностью вверх и сказать «Атака», все блоки разлетятся от вас кругом во все стороны. Чтобы защититься, скажите «Shield» (по-английски): блоки встанут перед вами выпуклым куполом, и чужое заклинание попадёт в них, а не в вас (каждый удар ломает несколько блоков, заклинания богов сметают весь купол; сзади и сверху он не прикрывает). «Shield» ещё раз — открыть. Когда вихрь кончается, блоки падают и ложатся обратно на землю. Вещи с земли он не берёт; не берёт воду, заколдованный камень и дары богов; не работает в космосе и в чужой защите дома. Держит концентрацию (другое заклинание — после «стоп»). Пока держите, тратит по 1 в секунду, пока вихрь существует; первое удачное поднятие даёт +8 ячеек маны.', dmg: '3 за блок', cost: 20, icon: 'assets/icons/ground_vortex.svg' },
    // the sphere of protection: only from the book of protection (HouseWards.js); a house is what it is mostly for
    { cat: 'guard', name: 'Invisibility', say: 'навести палочку на себя (или поднять вверх) + «Invisible» («Инвизибл»)', desc: 'Наведите палочку на себя или поднимите её вверх и скажите «Invisible» («Инвизибл»). Поможет спрятаться: вас не видят ни игроки, ни существа — жители, рыцари, волшебники, моряки, зомби, звери, драконы. Они лишь примерно помнят, где вы были, когда что-то сделали, и быстро теряют вас. Сами вы видите себя полупрозрачным, а ваши заклинания видны всем. Боссы видят невидимку всё равно. Держится, пока есть мана: тратит по 1 в секунду; «стоп» снимает. ', dmg: '—', cost: 20, icon: 'assets/icons/invisibility.svg' },
    { cat: 'guard', name: 'Protection House', say: 'направить палочку (руку) на дом — или на всё, что хотите защитить, — + «Protection House» («Протекшн Хаус»), держать палочку на куполе, пока он растёт, потом «стоп»', desc: 'Наведите палочку на дом или на то, что хотите защитить, и скажите «Protection House». Вырастет купол: держите палочку на нём, пока он растёт, — метр в секунду, по 3 маны за метр. Когда накроет всё нужное, скажите «стоп». Внутри свободно ходите вы и пущенные; снаружи в купол не войти: заклинания разбиваются, а ломящиеся теряют здоровье. Сломать могут только самые мощные — «Total Destruction», «Inspirius», «Бомбардо Максима», огонь «Let the Hellfire Come». Выучить можно только из книги защиты. Ещё по 3 за каждый метр. «Protection House Maxima» растёт вдвое быстрее.', dmg: '2 HP тому, кто ломится', cost: '20 + 3 за каждый метр роста', icon: 'assets/icons/ward.svg' },
    { cat: 'guard', name: 'Protection Invisible', say: 'направить руку на сферу защиты (на дом под защитой) + «Protection Invisible» («Протекшн Инвизибл»)', desc: 'Направьте руку на свою защиту и скажите «Protection Invisible» («Протекшн Инвизибл»). Всё, что внутри сферы, спрячется: издалека видна только трава, как вокруг, а подойдя ближе, вы снова увидите стены и тех, кто внутри. Работает только у хозяина там, где уже стоит «Protection House». Повторное слово всё показывает снова, бесплатно.', dmg: '—', cost: 15, icon: 'assets/icons/ward_hidden.svg' },
    { cat: 'guard', name: 'Protection House Grant', say: 'стоя у своей сферы защиты (или в ней), направить руку на игрока + «Protection House Grant» («Протекшн Хаус Грант»)', desc: 'Стоя у своей защиты или внутри неё, направьте руку на игрока и скажите «Protection House Grant» («Протекшн Хаус Грант»). Так вы пустите друга: он будет свободно проходить сквозь вашу защиту, и его слуги тоже. Ему придёт подсказка, что его пустили.', dmg: '—', cost: 5, icon: 'assets/icons/ward_grant.svg' },
    { cat: 'guard', name: 'Strengthen House', say: 'навести палочку (руку) на защиту своего дома — на купол или на дом под ним — + «Strengthen House» («Стренгзен Хаус», по-русски «Усили дом»)', desc: 'Наведите палочку или руку на защиту своего дома и скажите «Strengthen House» («Стренгзен Хаус», «Усили дом»). Поможет укрепить купол, чтобы его было труднее взломать: защита крепчает на 5 в секунду, пока держите луч, и на это тратится 5 маны в секунду. Предела нет: чем дольше укрепляете, тем сильнее купол. Отведёте палочку — луч гаснет, его можно поднять снова; «стоп» или конец маны тоже гасят. Пока луч идёт, другие заклинания не работают (кроме «Люмос», «Нокс» и «стоп»). Укреплять можно только свою защиту или ту, куда вас пустили. Выучить можно из книги защиты (тёмно-синяя книга с серебряным щитом).', dmg: '—', cost: '5 маны в секунду', icon: 'assets/icons/ward_strengthen.svg' },
    { cat: 'guard', name: 'Dispel Ward', say: 'направить руку на свою защиту дома (на купол или на дом под ним) + «Dispel Ward» («Диспел Вард»), и ещё раз в течение 6 секунд, не убирая руку', desc: 'Наведите руку на свою защиту и скажите «Dispel Ward» («Диспел Вард»), а потом ещё раз в течение 6 секунд, не убирая руку. Поможет снять свою защиту. Первое слово только предупреждает, сколько силы вы потеряете; второе гасит купол, дом снова виден всем, а вложенная сила пропадает. Допущенные игроки и чужие защиты снять её не могут. Потом защиту можно поставить заново. Выучить можно из книги защиты.', cost: 5, icon: 'assets/icons/ward_dispel.svg' },
    // ---- water
    { cat: 'water', name: 'Waterbollow', say: 'рука у самой воды + «Waterbollow»', desc: 'Подставьте руку к самой воде и скажите «Waterbollow» — вода поднимется живым шаром и будет следовать за рукой. Поможет перенести воду или ударить ледяным шаром (3–10 урона). Резкий рывок — и шар падает.', max: 'Максима: пока держите шар, он втягивает больше воды и растёт; можно повторять.', dmg: 'ледяной шар: 3–10', cost: 5, icon: 'assets/icons/water.svg' },
    { cat: 'water', name: 'Water forming', say: '«Water forming», пока вода жидкая', desc: 'Скажите «Water forming», пока вода жидкая, и ведите шар — за ним останутся водяные блоки. Поможет быстро возвести из воды стены, башни или дома.', dmg: '—', cost: 5, icon: 'assets/icons/water_forming.svg' },
    { cat: 'water', name: 'Wave Attack', say: 'стоя у воды, показать рукой НА воду + «Wave Attack»; волна встала — показать рукой, куда ей идти, и толкнуть рукой туда (или задержать руку)', desc: 'Стоя у воды, покажите рукой на воду и скажите «Wave Attack» — волна встанет и будет ждать, пока рука её держит. Толкнёте — покатится туда, куда показали: кого накроет, того сбивает с ног и уносит, костры гасит. По воде идёт далеко, по земле быстро слабеет. Не ранит, но и вас унесёт, если встанете перед ней. «Стоп» или опущенная рука — волна упадёт в воду.', max: 'Максима: «Wave Attack Максима» — волна почти вдвое шире и выше, идёт дальше, до 32 м, и сильнее; стоит 18 маны.', dmg: '—', cost: 8, icon: 'assets/icons/wave.svg' },
    { cat: 'water', name: 'Water Vortex', say: 'с палочкой в руке у воды показать НА воду + «Water Vortex» («вотер вортекс»), потом крутить рукой по кругу', desc: 'С палочкой в руке у воды скажите «Water Vortex» и в первые три секунды крутите рукой по кругу — вокруг поднимутся кольца воды. Каждый оборот добавляет воды: быстрее крутите — сильнее поток. Остановите руку и покажите цель или скажите «Атака» — кольца сольются в струю, её можно доворачивать. Сбивает с ног любое существо, не ранит. Струя летит не дальше 35 м, потом падает брызгами; рука, наведённая рядом с существом (в ~15°), подправляет полёт к нему. Поднятый заранее щит Protection её останавливает. Пока держите, тратит по 1 в секунду, пока в вихре есть вода; кончится мана — вода упадёт.', next: 'Дальше: «Bubble» (заранее, пока струя льётся или ещё 4 с после) — цель плавно поднимается в водяном пузыре; шар сам плавно идёт за рукой, как «Левиоса» (резкий рывок — сбросить); «стоп» — шар лопается, вода дождём падает вниз (изнутри спасает «Protection Maxima», руки буквой T). «Frozen» — пузырь замерзает: −1 ❤ в секунду от холода и −1 ❤ без воздуха; спасает только «Fire Maxima».', dmg: 'толчок; во льду −2/с', cost: '20 + 1/с', icon: 'assets/icons/vortex.svg' },
    { cat: 'water', name: 'Water Vortex Super Maxima', say: 'палочка в руке, встать у реки, озера или моря, показать палочкой НА воду + «Water Vortex Super Maxima» («вотер вортекс супер максима»)', desc: 'Встаньте у большой реки, озера или моря, покажите палочкой на воду и скажите «Water Vortex Super Maxima». Это водяной ответ «Адскому огню»: огромная масса воды поднимается и плывёт за палочкой — вытянутая рука шлёт её до 18 м. Поможет сбить с ног толпу врагов и погасить огонь, в том числе адский. Крутите рукой по кругу — вода превращается в бурю вокруг вас. Работает только там, где рядом много воды (не меньше 150 м³): лужа не подойдёт. Опасна и для вас, а щит лишь вдвое ослабляет её. Нужен максимум маны 100 и больше: тратит по 2 в секунду. «Стоп» её останавливает. Когда мана кончается, вода обрушивается большой волной. Впервые смыв существо или погасив огонь, вы получаете +20 к максимуму маны (один раз).', dmg: 'сбивает с ног, тонут: 1', cost: '80 + 2/с, «стоп» 50', icon: 'assets/icons/vortex_max.svg' },
    { cat: 'guard', name: 'Firefighting', say: 'направить руку (или палочку) на огонь + «Firefighting» («файрфайтинг», «фаер файтинг»)', desc: 'Направьте руку или палочку на огонь и скажите «Firefighting» — на долю секунды заклинание забирает воздух, а без воздуха огонь не горит. Поможет быстро потушить пожар в конусе до 15 м: костёр, горящие деревья и дома, «Инферно» и «Fire Maxima». Адский огонь только сбивает, полностью погасит его «Firefighting Максима». Людей и зверей конус слегка толкает. Если загорелись сами, поднимите палочку вверх: огонь на вас и рядом погаснет.', dmg: '— (только лёгкий толчок воздуха)', cost: 5, icon: 'assets/icons/firefighting.svg' },
    { cat: 'guard', name: 'Firefighting Максима', say: 'направить руку на огонь + «Firefighting Максима» («файрфайтинг максима»)', desc: 'Направьте руку на огонь и скажите «Firefighting Максима» («файрфайтинг максима»). Воздух уходит 5 секунд подряд, и конус идёт за рукой — водите рукой, и огонь гаснет везде, куда вы его направили. Поможет потушить даже адский огонь: в конусе он задыхается и гаснет. Шире и дальше обычного — до 25 м. «Стоп» прекращает раньше.', dmg: '— (только лёгкий толчок воздуха)', cost: 20, icon: 'assets/icons/firefighting_max.svg' },
    { cat: 'fight', name: 'Fire Maxima', say: 'показать рукой + «Fire Maxima» («файр максима»)', desc: 'Покажите рукой и скажите «Fire Maxima» — золотая огненная спираль полетит до 22 м и раскроется огненным цветком шириной около 6 м. Поможет растопить лёд: он тает там, где цветок, а если сказать «Fire Maxima» изнутри ледяного пузыря, лёд вокруг вас растает за секунду. Обжигает существ и поджигает деревья.', dmg: '6', cost: 20, icon: 'assets/icons/fire_maxima.svg' },
    { cat: 'water', name: 'Create a Board', say: 'рука на дерево + «Create a Board»', desc: 'Положите руку на дерево и скажите «Create a Board» — ствол станет доской для волн. Поможет выйти в море: несите её двумя руками за края, положите на воду и поднимите колено, чтобы встать одной ногой — доска повернётся по вам. Другой ногой гребите, наклоном поворачиваете. Отпустить можно, разжав руки. «Акцио» принесёт доску в руки. Поднимите ногу — и вы в воде. Доску можно взять из книги-птицы.', dmg: '—', cost: 6, icon: 'assets/icons/board.svg' },
    { cat: 'water', name: 'Air Bubble', say: 'в воде: обе руки к голове + «Air Bubble»', desc: 'В воде поднесите обе руки к голове и скажите «Air Bubble» — воздушный пузырь укроет голову, и под водой можно дышать 30 секунд. Без него воздуха хватит на 20 секунд, потом теряете здоровье. Поможет нырять и плыть: на поверхности гребите кролем или брассом, под водой плывите туда, куда смотрите. Без гребков тело держится на воде, а под водой медленно всплывает.', max: 'Максима: «Air Bubble Максима» (руки буквой T) — большой пузырь вокруг всего тела на 90 секунд.', dmg: '—', cost: 4, icon: 'assets/icons/air_bubble.svg' },
    // ---- move & things
    { cat: 'move', name: 'Анфёрл', say: 'поднять руку и показать на паруса корабля + «Анфёрл» («анферл», «unfurl»)', desc: 'Поднимите руку на корабль и скажите «Анфёрл» («анферл», «unfurl») — все паруса корабля опустятся. Чтобы корабль пошёл, дуйте «Вайндом» в паруса: они надуются, и корабль поплывёт по своему курсу, откуда бы ни дул ветер. Ветер тянется, пока есть мана (тратится 1 в секунду) или пока не скажете «стоп»; «Вайнд Максима» разгоняет корабль в несколько раз быстрее. Рулить можно штурвалом: положите ладонь на спицы, сожмите пальцы и ведите руку по кругу.', dmg: '—', cost: 6, icon: 'assets/icons/unfurl.svg' },
    { cat: 'move', name: 'Фёрл', say: 'показать на паруса + «Фёрл» («ферл», «furl», «убери паруса»)', desc: 'Покажите рукой на паруса и скажите «Фёрл» («ферл», «furl», «убери паруса») — паруса свернутся. Поможет остановить корабль: он ещё долго идёт по инерции, прежде чем встать.', dmg: '—', cost: 3, icon: 'assets/icons/furl.svg' },
    { cat: 'move', name: 'Up', say: 'лёжа на земле: вытянуть руку вперёд или поднять + «Up» («Ап», «Stand up» / «Стенд ап»); стоя или в воде: поднять руку чуть выше плеча (главное — не опускать) + «Up»', desc: 'Лёжа на земле скажите «Up» или «Stand up» — встанете сразу. Стоя на земле, на палубе, крыше или трапе, поднятая рука подбросит вас дугой туда, куда она показывает. В глубокой воде рука выбрасывает вас: вверх — назад в воду, вперёд — на берег или палубу. Приземляетесь мягко. Не работает в воздухе и если вас оглушили или заморозили.', dmg: '—', cost: 7, icon: 'assets/icons/up.svg' },
    { cat: 'move', name: 'Флайн', say: 'обе руки вверх + «Флайн»', desc: 'Поднимите обе руки и скажите «Флайн» — вы полетите. Рулите корпусом, а чтобы сесть, направьте себя в землю. «Паузин» — зависнуть на месте. Полёт тратит 2,5 маны в секунду в движении и 1,8 на месте, это больше восстановления. Учится только из быстрой летающей книги (голубая, с серебряной каймой).', dmg: '—', cost: 10, icon: 'assets/icons/flight.svg' },
    { cat: 'gods', name: 'Flying Maxima', say: 'в полёте (после «Флайн») + «Flying Maxima» / «Флайн Максима»', desc: 'Божественное заклинание: очень быстрый полёт — над Землёй и над любой планетой вы мчитесь вдоль поверхности намного быстрее обычного «Флайн» — и дорога в космос. Его нельзя найти или выучить со свитка: боги даруют его сильному волшебнику, у которого набирается 1000 ячеек маны. Взлетите «Флайн» и скажите «Flying Maxima» («Флайн Максима») — скорость быстро вырастает до 160 м/с, поворачивайте и поднимайтесь корпусом, как обычно. Чтобы улететь в космос, направьте полёт почти вертикально вверх (примерно 90°, не меньше 80°) и держите так 5 секунд подряд: ветер усилится, края экрана побелеют — отсчёт идёт на экране. Наклонились или выровнялись — отсчёт начнётся заново. Потом небо темнеет, и вы оказываетесь над круглой Землёй. В космосе летите так же корпусом, а «Паузин» зависнет на месте. Вернуться можно, подлетев к Земле: войдёте в атмосферу и окажетесь над тем местом, куда летели. На Луне, Меркурии, Венере, Марсе и Плутоне можно сесть. Первый полёт с ним даёт +100 ячеек маны. Подробнее — в «Механике игры», раздел «Космос». В полёте тратит ещё 1,5 в секунду.', dmg: '—', cost: '30, пока несёт — 1,5/с + «Флайн» 2,5/с (+0,5/с дыхание без воздуха)', icon: 'assets/icons/flight_max.svg' },
    { cat: 'gods', name: 'Create a Planet', say: 'в космосе: поднятая рука или палочка на скопление метеоритов + «Create a Planet» / «Создай планету»', desc: 'В космосе поднимите руку или палочку на скопление метеоритов и скажите «Create a Planet» («Создай планету»). Метеориты сыплются в одну точку, и на месте скопления появляется планета. Назвать её можно в течение минуты: «Назови Аврора». Она безжизненная: камень и пыль, воздуха нет, тяжесть маленькая — взлетать легко. Скопления есть в поясе астероидов за Марсом и в поясе Койпера, на карте они отмечены ☄️. Скопление уходит насовсем: их всего 13 на мир. Найти можно в библиотеке храма богов на Венере. Первое использование даёт +100 ячеек маны.', dmg: '—', cost: 500, icon: 'assets/icons/planet_create.svg' },
    { cat: 'gods', name: 'Enlarge Planet', say: 'в космосе рука или палочка на планету (или стоя на ней) + «Enlarge Planet» / «Увеличь планету»', desc: 'В космосе направьте руку или палочку на планету (или встаньте на ней) и скажите «Enlarge Planet» («Увеличь планету»). Планета станет на 30% больше, и тяжесть на ней возрастёт на 30%. Одну планету можно увеличить не больше трёх раз. Земля на поверхности остаётся прежней, и постройки игроков не ломаются. Работает на каменных планетах, Луне, созданных планетах и газовых гигантах. Не работает на Солнце, Земле и Венере (её защищает храм богов). Первое использование даёт +100 ячеек маны.', dmg: '—', cost: 100, icon: 'assets/icons/planet_enlarge.svg' },
    { cat: 'gods', name: 'Terraform Planet', say: 'из космоса рука или палочка на планету, или стоя на ней + «Terraform Planet» / «Терраформируй планету»', desc: 'Из космоса направьте руку или палочку на планету (или встаньте на ней) и скажите «Terraform Planet» («Терраформируй планету»). Планета станет живой, как Земля, но не такой же: за около 20 секунд её покроют атмосфера, облака, вода и зелень. Многое зависит от расстояния до Солнца: близко к нему воздух выкипит; у орбиты Венеры будет жаркая пустыня, от неё до Марса — зелёная зона с лесами и морями, дальше — ледяной мир до Юпитера, а ещё дальше Солнце не греет, и планету сначала надо придвинуть. У каждой планеты свои трава, деревья и моря. Животных нет. Постройки игроков остаются, но там, где они стоят, деревья не вырастут. Не работает на Солнце, газовых гигантах, Земле, Венере и уже живой планете. Первое использование даёт +100 ячеек маны.', dmg: '—', cost: 1000, icon: 'assets/icons/planet_terraform.svg' },
    { cat: 'gods', name: 'Wingardium Leviosa Super Maxima', say: 'в космосе рука или палочка на планету + «Вингардиум Левиоса Супер Максима»', desc: 'В космосе направьте руку или палочку на планету и скажите «Вингардиум Левиоса Супер Максима». Планета пойдёт за рукой: поможет перенести её ближе к Солнцу или дальше, чтобы подобрать ей климат. Тяжёлая, она идёт не быстрее 1,6 км/с, а «Стоп» отпускает её на новой орбите. Держится, пока держите руку: тратит по 3 в секунду; другие заклинания в это время не работают. Не работает на Солнце, Земле, Луне и Венере (её защищает храм богов). Первое использование даёт +100 ячеек маны.', dmg: '—', cost: '100 + 3/с', icon: 'assets/icons/planet_move.svg' },
    { cat: 'gods', name: 'Бум', say: 'поднять руку или палочку и навести на любую землю — поле, берег, гору, скалу или замок (до 230 м) + «Boom» / «Бум» — одно слово, отдельной командой', desc: 'Поднимите руку или палочку на землю — поле, берег, гору, скалу или замок, до 230 м — и скажите отдельным словом «Boom» или «Бум». Это сила богов, в 10 раз сильнее «Инспириуса». Ничего не вылетает: земля разрывается изнутри, сначала дрожит и трескается, потом глыбы летят во все стороны. Поможет стереть с лица мира гору или крепость: на месте остаётся кратер около 110 м, а у моря его затопит, и получится бухта. Кто был рядом, погибает, остальных сбивает с ног. Не действует на небо, в открытом космосе и на дары богов. Ни одна защита боссов его не держит, даже проклятие Чёрных Усов и ледяную сущность Королевы. Обычная речь «бум» не срабатывает. Первое использование даёт +100 ячеек маны.', dmg: '−1000 / −150 / −40', cost: 750, icon: 'assets/icons/boom.svg' },
    { cat: 'gods', name: 'Planet Liquidation', say: 'в космосе: поднятая рука или палочка на планету + «Planet Liquidation» / «Плэнет ликвидэйшн» / «Уничтожь планету»', desc: 'В космосе поднимите руку или палочку на планету и скажите «Planet Liquidation» («Плэнет ликвидэйшн», «Уничтожь планету»). Из руки вырвется малиновый луч, и примерно через 12 секунд планета взорвётся. Поможет полностью стереть планету: её не станет на карте, а всё построенное на ней исчезнет. На орбите останутся обломки, из которых можно снова создать планету. Кто в этот момент стоит на ней или летит в её воздухе, погибает; предупреждение получают все на планете, у них есть время улететь. Цена зависит от массы планеты: чем она тяжелее, тем дороже. Не действует на Землю и Венеру (их защищает сила богов) и на Солнце. Первое использование даёт +100 ячеек маны.', dmg: 'планета взрывается; кто на ней — погибает', cost: '1500 + масса', icon: 'assets/icons/planet_liquidation.svg' },
    { cat: 'gods', name: 'Protection Gods', say: 'вытянуть руку + «Protection Gods» / «Протекшн Гадс» / «Божественная защита»', desc: 'Вытяните руку и скажите «Protection Gods» («Протекшн Гадс», «Божественная защита»). Это золотой щит, сильнее обычного Protection: он не пропускает ни одно заклинание, кроме божественных, — ни урона, ни толчка, ни заморозки. Поможет пережить даже взрывы и землетрясение. Удары оружием и стрелы держит щит, повёрнутый к ним. Божественные заклинания он тоже не пропускает, но за них тратится половина их цены; если маны не хватит, щит ломается. Держится, пока не скажете «стоп». Работает на Земле, в космосе и на планетах. Найти можно в библиотеке храма богов на Венере. Первое использование даёт +100 ячеек маны. Пока держите, тратит по 3 в секунду.', dmg: 'не пропускает ни одного заклинания, кроме божественных', cost: '100 + 3/с', icon: 'assets/icons/protection_gods.svg' },
    { cat: 'gods', name: 'Protection Gods Maxima', say: 'руки в стороны буквой «T» + «Protection Gods Maxima» / «Протекшн Гадс Максима» / «Божественная защита Максима»', desc: 'Разведите руки буквой T и скажите «Protection Gods Maxima» («Протекшн Гадс Максима», «Божественная защита Максима»). Вокруг всего тела встанет золотой купол. Поможет пережить любой взрыв: он не пропускает ни одного заклинания, кроме божественных, с какой стороны ни бей, и полностью спасает от взрывов, своих и чужих. Божественные заклинания тоже не пропускает, но за них тратится половина цены; если маны не хватит, купол сломается. Если взрывают планету, на которой вы стоите, и купол выдержал, вас отбросит в космос живым. Держится, пока не скажете «стоп». Найти можно в библиотеке храма богов на Венере. Первое использование даёт +100 ячеек маны. Пока держите, тратит по 5 в секунду.', dmg: 'не пропускает ни одного заклинания, кроме божественных', cost: '300 + 5/с', icon: 'assets/icons/protection_gods_maxima.svg' },
    { cat: 'gods', name: 'Империус Максима', say: 'направить руку на любое существо или игрока, не дальше 900 м, + «Империус Максима» («Imperius Maxima»)', desc: 'Направьте руку на любое существо или игрока не дальше 900 м и скажите «Империус Максима» («Imperius Maxima») — это заклинание богов. Поможет подчинить кого угодно, даже дракона, сову, феникса, паучиху или капитана Чёрные Усы: существо начинает слушаться ваших рук. Летающие поднимаются от ваших взмахов обеими руками, а дракон дышит огнём, когда вы тянете долгий звук «У-у-у»: пламя поджигает деревья, дома, траву, жителей, животных, зомби и корабли (драконы, совы и Ледяная Королева не горят). Дракон огромный и тяжёлый: взмах крыла, удар хвоста или пикирование ломают стены, крыши, деревья и корабли и отбрасывают существ — чем быстрее вы машете и летите, тем сильнее разрушение, а медленное касание почти ничего не ломает. Земля, вода, дары богов, храм богов и заколдованный камень ему не поддаются. Чтобы дракон шёл, шагайте на месте; остановились — он стоит. В сети можно подчинить и другого игрока, но сильный удар по нему вырвет его из-под контроля. Связь держится до 1800 м: с 900 м экран темнеет, на 1800 м она рвётся. Если погибнет подвластный игрок — это его обычная смерть, а вы возвращаетесь в своё тело. Пока держите, тратит по 2 в секунду. Найти можно в библиотеке храма богов на Венере.', dmg: 'сила самого существа', cost: '500 + 2/с', icon: 'assets/icons/imperius_max.svg' },
    { cat: 'gods', name: 'Да пусть создастся', say: 'направить палочку на землю + «Да пусть создастся …» и сразу описать, что создать (одной фразой, или после «Да пусть создастся» сказать описание следующей фразой)', desc: 'Это заклинание богов позволяет вам создать всё, что вы опишете словами: от колодца, моста или статуи свиньи до дома, замка с башнями и рвом или целого города с улицами, площадью и стенами. А ещё — своё собственное существо или растение. Чтобы создать, направьте палочку на землю и скажите, например: «Да пусть создастся замок из белого камня с шестью башнями и рвом», «Да пусть создастся существо с большими глазами, тонкими ногами и крыльями, умеющее летать, 50 здоровья» или «Да пусть создастся дерево с синими листьями, которое светится и быстро размножается в лесу». Боги прочтут ваши слова — над землёй вырастет золотое зерно света, — а потом постройка соберётся из летящих блоков: передом к вам, передний край там, куда смотрела палочка. Двери в ней открываются рукой, на кроватях можно лечь, в сундуки — складывать вещи. Существо может быть похоже на любое животное — скажите, например, «похожее на коня», «как слон», «волк», «дракон»: у него будет настоящее тело этого зверя (у коня — длинные ноги, грива и копыта, у слона — хобот и бивни). Цвета ложатся туда, куда вы их назвали: «белый конь с чёрной гривой». Без слов о размере всё получается обычного среднего размера, а «большой», «огромный», «очень-очень большой» или «маленький» меняют его. Существу можно задать вид, ходьбу и полёт (по 10 способов), размер, здоровье (обычно 20), характер и умения: дышать огнём, плеваться водой, светиться, лечить друзей и другие. Растение само растёт и расселяется там, где вы сказали. Если боги не поймут описание или будут думать дольше 40 секунд, мана вернётся. Свиток — в библиотеке храма богов на Венере. Первое творение даёт +100 ячеек маны.', dmg: 'никого не ранит; созданное существо — своими умениями', cost: 1000, icon: 'assets/icons/divine_creation.svg' },
    { cat: 'move', name: 'Let it rain', say: 'рука или палочка к небу + «Let it rain»', desc: 'Поднимите руку или палочку к небу и скажите «Let it rain». Небо затянут тучи, и начнётся гроза: ливень и молнии вдали на 2 игровых часа (2 минуты). Поможет вызвать грозу, в которой работает Молот Тора. Погоду видят все игроки. Прекратить можно заклинанием «To the Sun».', dmg: '—', cost: 20, icon: 'assets/icons/rain.svg' },
    { cat: 'move', name: 'To the Sun', say: 'рука к небу (в дождь или под чёрными тучами горгулий) + «To the Sun»', desc: 'Поднимите руку или палочку к небу во время дождя и скажите «To the Sun» — тучи расходятся, и дождь с грозой кончаются. Золотой луч идёт за вашей палочкой: куда ведёте палочку, туда и луч. Это же заклинание — единственный способ уничтожить горгулий насовсем: направьте палочку на чёрные тучи их ритуала, и луч вступит с тучами в борьбу (подробности — в «Пентаграмма адских горгулий»).', dmg: '—', cost: 12, icon: 'assets/icons/sun.svg' },
    { cat: 'move', name: 'Акцио', say: 'поднять руку, указать на предмет + «Акцио»', desc: 'Это простейшее заклинание: его волшебник может творить без палочки, голой рукой. Поднимите руку, укажите на вещь до 60 м и скажите «Акцио» — вещь прилетит в свободную руку: меч, лук, щит, палочка, свиток, еда, монеты. Пригодится, чтобы подобрать вещь, не бегая за ней. Доска для волн большая: если свободны обе руки, она ляжет поперёк перед грудью, если одна — под мышку, а если руки заняты, упадёт у ваших ног.', dmg: '—', cost: 5, icon: 'assets/icons/accio.svg' },
    { cat: 'move', name: 'Алохомора', say: 'показать рукой (или палочкой) на замок рядом, до 5 м + «Алохомора»', desc: 'Покажите рукой или палочкой на замок рядом (до 5 м) и скажите «Алохомора». Поможет открыть запертое: сундук в замке, деревне или доме жителя щёлкнет и приоткроется, и его можно поднять рукой. Запертую дверь дома жителя тоже откроет. Но если житель или стража видит, как вы вскрываете чужое, это кража, и хозяева пойдут на вас. Никто не видел — ничего не будет. Отпирает и дверь, запертую заклинанием «Lock». Сундуки в пещерах и так открыты. Не действует на людей и животных.', dmg: '—', cost: 5, icon: 'assets/icons/alohomora.svg' },
    { cat: 'move', name: 'Lock', say: 'показать рукой (или палочкой) на дверь рядом, до 5 м + «Lock» («Лок», «Lock door»)', desc: 'Покажите рукой или палочкой на дверь рядом, до 5 м, и скажите «Lock» («Лок»). Поможет запереть дом или комнату: дверь закроется, щёлкнет замок, и открыть её сможет только тот, кто скажет «Алохомора». Даже вы сами рукой её не откроете, а люди постучат и пойдут другой дорогой. Не спасает от взрыва, оружия или огня: они ломают дверь, как обычную. Говорите отдельным словом. ', dmg: '—', cost: 3, icon: 'assets/icons/lock.svg' },
    { cat: 'move', name: 'Алохомора Максима', say: 'показать рукой на ворота + «Алохомора Максима»', desc: 'Покажите рукой на ворота тронного зала и скажите «Алохомора Максима». Поможет открыть крепкий замок: ворота, которые для вас заперты, приоткроются, дальше их толкаете рукой. Простая «Алохомора» их не берёт. Рыцари и король проходят через эти ворота свободно. Ворота кованые, железные: обычное «Бомбардо» по ним только звенит. Разбить их можно «Бомбардо Максима», «Инспириусом» или «Total Destruction Максима» (в старых мирах ворота деревянные — там хватит двух обычных «Бомбардо»), но стража на взлом нападёт. В захваченном вами замке ворота открыты для вас.', dmg: '—', cost: 25, icon: 'assets/icons/alohomora_max.svg' },
    { cat: 'move', name: 'Атак', say: 'пока меч или топор парит («Вингардиум Левиоса») + «Атак»', desc: 'Пока меч или топор парит в воздухе, скажите «Атак» — оружие полетит в ближайшее живое существо и вонзится в него. Если рядом никого нет, полетит туда, куда показывает рука. Поможет поразить врага на расстоянии. Раненый теряет здоровье, и течёт кровь. Вынуть оружие можно рукой, «Акцио» или «Левиосой» — тогда кровь идёт вдвое медленнее, пока не скажете «Rescue».', dmg: '4–5 + кровь', icon: 'assets/icons/attack.svg' },
    { cat: 'guard', name: 'Rescue', say: 'пальцы к своей ране + «Rescue» (или рукой на раненого)', desc: 'Приложите пальцы к своей ране и скажите «Rescue» или положите руку на раненого. Поможет остановить кровотечение. Если оружие ещё в ране, заклинание его вынет.', dmg: '—', icon: 'assets/icons/rescue.svg' },
    { cat: 'move', name: 'Вингардиум Левиоса', say: 'направить руку на предмет + «Вингардиум Левиоса»', desc: 'Направьте руку на предмет, животное, человека, другого волшебника или тело до 30 м и скажите «Вингардиум Левиоса». Предмет поднимется и последует за рукой: так удобно переносить вещи и даже тела. Живые в воздухе пугаются и вырываются, а волшебник сам вырывается через несколько секунд. Резкий рывок — бросок: брошенный летит, падает, кувыркается и теряет здоровье тем больше, чем сильнее удар; рыцаря бережёт доспех. Того, в кого врезались, тоже сбивает с ног. Если не вышло, подсказка скажет почему: щит, защита дома, кто-то на пути или его уже держат.', dmg: '—', cost: 6, icon: 'assets/icons/levitation.svg' },
    { cat: 'move', name: 'Вингардиум Левиоса Максима', say: 'направить руку (или палочку) на людей, вещь на земле, дерево, дом, стену, землю или корабль + «Вингардиум Левиоса Максима» («Левиоса Максима»)', desc: 'Направьте руку или палочку на людей, вещь на земле, дерево, дом, стену, землю или корабль и скажите «Вингардиум Левиоса Максима» («Левиоса Максима»). Поможет поднять целую группу или строение: всё и всех до 7 м вокруг цели поднимает и держит в воздухе. Дерево, дом, кусок стены или глыбу земли выкорчевывайте палочкой: раскачивайте её и тяните вверх. Корабль поднимается из воды целиком, с экипажем. Резкий замах рукой — и поднятое летит и разбивается о землю или о того, в кого попало. «Стоп» или конец маны — всё падает. Пока держите, тратит по 2 в секунду. Драконов, фениксов и книги-птицы не берёт. ДИРИЖЁР ПРЕДМЕТОВ: направьте палочку на вещь, лежащую на земле, и скажите заклинание ОДИН раз — вещь послушна. Дальше ничего говорить не надо: просто указывайте палочкой (на полсекунды) на другие вещи — каждая поднимется и повиснет в воздухе, покачиваясь (до 32). Они идут за палочкой цепочкой, как паровозик, по очереди, с запозданием. Крутите рукой кругами вокруг себя — вещи закручиваются вихрем вокруг вас (быстрее рука — быстрее вихрь); перестали крутить — снова идут за палочкой. «Shield» («Щит») — вещи смыкаются в стену там, куда смотрит палочка: чужие заклинания и снаряды попадают в вещи, а не в вас (вещь, принявшая сильный удар, выбита из стены и падает; божественные заклинания стену сметают). «Атак» — вещи по очереди летят в того, на кого направлена палочка: ранят по весу и скорости и толкают. «Стоп» или конец маны — все вещи падают. Не берёт дары богов (пьедесталы, Ледяной Жезл) и неоплаченный товар; оружие и книги поднимает обычная «Левиоса». Тратит по 2 в секунду, плюс по 0,3 в секунду за каждую вещь после первой (всего не больше 8 сверху).', dmg: 'падение 5–45; вещи в залпе до 10', cost: 50, icon: 'assets/icons/levitation_max.svg' },
    // ---- build
    { cat: 'build', name: 'Gather', say: 'указать на дерево / камень / землю + «Gather» или «Assemble»', desc: ' Укажите рукой или палочкой на дерево, камень или землю до 20 м и скажите «Gather» или «Assemble». Поможет собрать материалы: дерево целиком превращается в древесину своего вида, 20 штук, а вещи на земле, например у тела погибшего, попадают к вам. Рука не обязана целиться точно: ствол или крона рядом с линией тоже подойдут.', dmg: '—', cost: 3, icon: 'assets/icons/gather.svg' },
    { cat: 'build', name: 'Create a Floor', say: 'выбрать ресурс + «Create a Floor», тянуть руку', desc: 'Выберите ресурс, скажите «Create a Floor» и тяните руку — пол растёт блок за блоком за рукой. Поможет быстро застелить комнату или площадку. С водяным шаром в руке пол получается изо льда.', dmg: '—', cost: 4, icon: 'assets/icons/floor.svg' },
    { cat: 'build', name: 'Stitching', say: 'направить палочку (руку) на проход + «Stitching» («Стичинг»)', desc: 'Направьте палочку или руку на проход — дыру в пещере, проём без двери в стене, дыру в полу или потолке — и скажите «Stitching» («Стичинг»). Поможет заделать дыру без лишних камней: камни того же материала слетаются со стен и ложатся в проход, получается твёрдая стена, которую ломает «Бомбардо». Работает только там, где проход окружён материалом: в открытом поле или небе не сработает. В человека или зверя камень не кладётся, он ждёт, пока тот отойдёт. ', dmg: '—', cost: 7, icon: 'assets/icons/stitching.svg' },
    { cat: 'build', name: 'Create a Bridge', say: 'направить палочку на твёрдое место (стену, другой берег, скалу) + «Create a Bridge» («Криейт э бридж», «Бридж», «Создай мост»)', desc: 'Мост вырастает от вас до того места, куда указывает палочка: над рекой, пропастью, морем, в гору или на башню, вниз с обрыва, на расстояние до 200 метров. Чтобы создать: поднимите палочку, направьте её на твёрдое место (стену, другой берег, скалу) и скажите «Create a Bridge» («Создай мост»). Мост идёт от того уровня, где стоят ваши ноги, настил в три шага шириной, вверх и вниз не круче, чем под 45°, и растёт на глазах. Он ложится только в пустоту (воздух, вода), чужие постройки не заменяет. Материал берётся от вашего места и от того, во что упёрлась палочка. Ходят по нему все, и игроки, и существа; ломается взрывами. Известно сразу. Стоит 10 маны, для длинных (больше 16 м) чуть больше — около 100 за 200 метров.', dmg: '—', cost: 10, icon: 'assets/icons/bridge.svg' },
    { cat: 'build', name: 'Create a Wall', say: '«Create a Wall», вести руку вбок и вверх', desc: 'Скажите «Create a Wall» и ведите руку вбок и вверх — стена растёт за рукой в ширину и в высоту. Поможет быстро отгородиться или поставить укрытие.', dmg: '—', cost: 4, icon: 'assets/icons/wall.svg' },
    { cat: 'build', name: 'Create a Ceiling', say: '«Create a Ceiling», тянуть руку', desc: 'Скажите «Create a Ceiling» и тяните руку — потолок на высоте трёх блоков вырастет над вами. Поможет накрыть комнату или укрытие.', dmg: '—', cost: 4, icon: 'assets/icons/ceiling.svg' },
    { cat: 'build', name: 'Build a Roof', say: '«Build a Roof», тянуть руку', desc: 'Скажите «Build a Roof» и тяните руку — вырастет двускатная крыша: ступени идут от краёв к коньку. Поможет закрыть дом сверху.', dmg: '—', cost: 6, icon: 'assets/icons/roof.svg' },
    { cat: 'build', name: 'Create a Door', say: 'держа дерево (≥ 12) + «Create a Door»', desc: 'Держите дерево, не меньше 12 штук, и скажите «Create a Door»: кубик дерева превратится в дверь, и отводя руку, вы её растянете. Поможет сделать вход в дом или комнату. Чтобы поставить дверь, скажите «Stand» на нужном месте.', dmg: '—', cost: 6, icon: 'assets/icons/door.svg' },
    { cat: 'build', name: 'Create a Bed', say: 'показать рукой или палочкой на землю + «Create a Bed» / «Создай кровать»', desc: 'Понадобятся 4 бревна и 3 клубка шерсти: достаточно держать их в руках или в запасе. Покажите рукой или палочкой на место и скажите «Create a Bed» («Создай кровать») — со вспышкой искр встанет белая кровать. Поможет обустроить ночлег без долгого строительства. Можно и по-старому: положить материалы на землю рядом, хватит их общего количества. Если чего-то не хватает, подсказка скажет чего.', dmg: '—', cost: 6, icon: 'assets/icons/bed.svg' },
    { cat: 'build', name: 'Create a House', say: 'палочкой на землю, где поставить дом + «Create a House» / «Создай дом»', desc: ' Понадобятся 3 шерсти и 10 песка, песок собирается «Gather» на пляже или у реки; рядом должны расти хотя бы 3 дерева. Наведите палочку на землю и скажите «Create a House» («Создай дом»). Десять секунд вокруг вспыхивают искры, деревья исчезают, песок становится стеклом, шерсть — кроватью, и встаёт домик с крышей, дверью, комнатой с кроватью и кладовой с сундуком. Каждый дом немного другой. Держите палочку всё время: если отпустите или кончится мана, магия сорвётся и начнётся пожар. Пока держите, тратит по 0,5 в секунду.', dmg: '—', cost: '20 + 0,5/с', icon: 'assets/icons/house.svg' },
    { cat: 'build', name: 'Create a Castle', say: 'палочку туда, где встанет замок, + «Create a Castle» / «Создай замок» (слышится и как «криейт э касл»)', desc: 'Наведите палочку туда, где встанет замок, и скажите «Create a Castle» («Создай замок»). Целый замок из тёмного камня с высокими башнями, воротами и тронным залом появится примерно за полминуты. Поможет получить крепость без строительства. Нужно 500 маны и камень рядом: скалы или каменная порода под землёй. На песчаном берегу или над водой не получится. Замок встанет примерно в 45 м перед вами, на ровном сухом месте без построек. Всё время держите палочку: если выпустите, рост остановится, а что успело вырасти, останется. Внутри тронный зал с золотым троном, спальня с четырьмя кроватями и сокровищница с пустыми сундуками.', dmg: '—', cost: '500', icon: 'assets/icons/castle.svg' },
    { cat: 'build', name: 'Create an Ice Castle', say: '«Create an Ice Castle» («криейт эн айс касл», «айс касл», «создай ледяной замок»), потом топнуть ногой, потом поднять обе руки снизу вверх', desc: 'Скажите «Create an Ice Castle» («айс касл»), топните ногой и поднимите обе руки снизу вверх — из-под ног вырастет ледяной дворец. Поможет построить убежище или крепость там, где рядом вода или снег. Замок растёт вслед за руками, а когда руки подняты прямо вверх, купол смыкается, и замок готов. Внутри ледяные ворота, зал под куполом, лестница на галерею, ледяной трон и кровать. Пока замок растёт, держится концентрация. Огонь растапливает стены: «Инферно», «Fire Maxima» и «Адский огонь». В тепле замок тает к концу вторых игровых суток, а в снежных горах не тает никогда.', dmg: '—', cost: 500, icon: 'assets/icons/ice_castle.svg' },
    { cat: 'build', name: 'Ice Bridge', say: 'показать рукой на место, куда вести мост + «Ice Bridge» («айс бридж», «создай ледяной мост»)', desc: 'Покажите рукой на место, где мост должен кончиться (от 5 до 60 м), и скажите «Ice Bridge» («айс бридж»). Поможет перебраться через обрыв, реку или яму: от ваших ног аркой растёт ледяной мост, вслед за рукой. Нужны вода или снег рядом, до 18 м. Настил в три блока с ледяными перилами; по мосту ходят и люди, и звери. Огонь его растапливает, в тепле он тает за пару игровых суток, а в снежных горах не тает.', dmg: '—', cost: 50, icon: 'assets/icons/ice_bridge.svg' },
    { cat: 'build', name: 'Improve a House', say: 'палочкой на ресурсы рядом с домом + «Improve a House» / «Улучши дом»', desc: ' Выйдите из своего дома, бросьте рядом нужные ресурсы и скажите «Improve a House» («Улучши дом»): за 10 секунд дом превратится в больший — появятся второй этаж и балкон, а на пятом уровне — большой каменный дом. Поможет расширить жильё. Каждый уровень вдвое дороже: второй — 6 шерсти, 20 песка, 4 дерева и 40 маны; третий — 12, 40, 6 и 80; четвёртый — 24, 80, 8 и 160; пятый — 48, 160, 10 и 320. Вещи в сундуках не пропадают. Новый уровень — не раньше чем через 3 минуты.', dmg: '—', cost: '40…320', icon: 'assets/icons/house_improve.svg' },
    { cat: 'build', name: 'Change a color', say: 'показать на кровать + «Change a color синий» / «Поменяй цвет на красный»', desc: 'Покажите на кровать (до 12 м) и скажите «Change a color» с нужным цветом, например «Поменяй цвет на красный». Кровать сразу перекрасится, это поможет разнообразить обстановку. Доступны белый, красный, синий, зелёный, жёлтый, оранжевый, фиолетовый, розовый, голубой, чёрный, коричневый и серый.', dmg: '—', cost: 2, icon: 'assets/icons/recolor.svg' },
    { cat: 'build', name: 'Breakthrough', say: 'обе руки чуть ниже горизонта перед собой, потом поднять их вместе (за 3 с) + «Breakthrough»', desc: 'Держите обе руки чуть ниже горизонта перед собой и поднимите их вместе за три секунды, скажите «Breakthrough». Из земли поднимется стена из камня и земли — укрытие от заклинаний и зомби. Тех, кто стоял там, отбрасывает назад.', max: 'Максима: «Breakthrough Максима» — стена 9 на 5 блоков и сбивает с ног; стоит 20 маны.', dmg: '—', cost: 10, icon: 'assets/icons/breakthrough.svg' },
    { cat: 'build', name: 'Fire', say: 'поднять руку, показать на землю (до 25 м) + «Fire» / «Файр» / «Костёр»', desc: 'Покажите рукой на землю до 25 м и скажите «Fire» — загорится костёр: на земле или полу, а на стене — у её подножия. Горит 3 минуты. Поможет осветить ночь или пещеру и сварить мясо или рыбу. Если держать у огня руку с древесиной, каждый блок добавит минуту, до 10. Стоять в огне горячо: −1 здоровья в секунду. На воде не горит.', dmg: '1/с, если стоять в огне', cost: 4, icon: 'assets/icons/campfire.svg' },
    { cat: 'build', name: 'Stand', say: '«Stand» / «стоп»', desc: 'Скажите «Stand», чтобы завершить стройку: то, что растёт за рукой, встаёт на место. Слово «стоп» останавливает всё, что действует: щит, Левиосу, водяной шар, огонь и лёд в руках, «Акцио», полёт. Люмос «стоп» не гасит, его гасит только «Нокс».', dmg: '—', icon: 'assets/icons/stand.svg' },
    // ---- wand only
    { cat: 'wand', name: 'Fireworks', say: 'поднять палочку вверх + «Fireworks» («Файрворкс», «Фаер воркс»)', desc: 'Поднимите палочку вверх и скажите «Fireworks» — в небе взорвутся ракеты: пионом, хризантемой, кольцом, звездой или сердцем. Поможет устроить салют к празднику или победе. Салют идёт 10 секунд; опустите палочку — залпы ждут, поднимите — продолжаются. «Стоп» гасит салют. Видно за много сотен метров. Никого не ранит и ничего не поджигает; жители любуются.  Первый раз даёт 3 ячейки маны.', dmg: '—', cost: 15, icon: 'assets/icons/fireworks.svg' },
    { cat: 'wand', name: 'Visible Godi', say: 'палочка в руке + «Visible Godi» («Визибл Годи» — оба слова вместе; одно слово не сработает), потом водить палочкой по стене, как кистью', desc: 'Пока держите, тратит по 1 в секунду, пока заклинание держится; «стоп», конец маны, оглушение или смерть прекращают его. Пока оно держится, другие заклинания не работают (кроме «стоп», Люмос, Нокс, Protection) — сначала «стоп». Из палочки идёт густой белый пар: куда она смотрит, там остаётся клуб пара — вы РИСУЕТЕ им тучку, водя палочкой (на стене пар липнет к её поверхности, на открытом месте повисает в нескольких шагах). Пара не бесконечно: порция кончается примерно на три десятка клубов (если держать палочку неподвижно, пар не тратится), потом струя иссякает; нарисованное редеет само и пропадает секунд через сорок пять. Пар не толкает, не ранит, никого не пугает и не мешает ходить. Все игроки рядом видят и струю, и нарисованную тучку. Но СМОТРЕТЬ сквозь неё может только тот, кто её нарисовал: подойдите к стене ближе трёх шагов (не дальше) и взгляните на свой пар — там, где он закрывает стену, стена не рисуется, и видно то, что за ней. Чем стена проще и тоньше — тем чётче: один блок дерева (стена, дверь, борт корабля) — почти как есть, листва и забор — как окно; один блок земли или кирпича — хорошо; один блок камня — заметно хуже (около двух третей), три блока камня — смутно (около четверти), шесть — только тёмные силуэты, восемь и больше — ничего, одно молоко. Чем хуже видно, тем сильнее размытие, зерно и серо-голубой оттенок. Видно ровно то, что за этой стеной: комнату за ней, а её дальняя стена — уже просто стена (сквозь две стены с комнатой между ними не смотрят). Жители за стеной не знают, что на них смотрят, и не оборачиваются. Не пускает взгляд магия: заколдованный камень (арены, стены башен волшебников), арканный камень, лёд Ледяной Королевы, храм богов, проклятый корпус чёрного корабля и защита чужого дома — вместо картинки молочное «ничего» и подсказка «Магия этой стены не пускает ваш взгляд». Вода — не стена. В первый раз, когда пар по-настоящему показал то, что за стеной, максимум маны растёт на 5 ячеек.', dmg: '—', cost: 20, icon: 'assets/icons/visible_godi.svg' },
    { cat: 'wand', name: 'Раскрой свои секреты', say: 'палочку (или просто руку) навести на предмет + «Раскрой свои секреты»', desc: 'Наведите палочку или просто руку на предмет и скажите «Раскрой свои секреты». Над предметом появится голограмма: что это за вещь и какие у неё свойства — сила, направление, особое заклинание. Без цели заклинание расскажет о предмете в руке или о самой палочке.', dmg: '—', icon: 'assets/icons/reveal.svg' },
    { cat: 'wand', name: 'Люмос', say: 'палочка в руке + «Люмос»', desc: 'Скажите «Люмос» с палочкой в руке — на её кончике загорится свет. Поможет осветить путь в пещере или ночью, и свет не мешает другим заклинаниям этой палочкой. Свет понемногу тратит ману и горит, пока вы его не погасите или не пошлёте вперёд. Пока он горит, можно сказать «Flashlight» — фонарик, или «Ahead» — шарик света полетит вперёд, замедлится, отскочит от стен и погаснет через 15 секунд. Погасить всё можно только словом «Нокс»; «стоп» Люмос не гасит. С руками V4 в настройках палочку видно в вашей руке и в игре она поворачивается так же.', max: 'Максима: «Люмос Максима» — ярче; повторное слово делает свет ещё ярче, до пятикратного, но тратит больше сил.', dmg: '—', cost: 2, icon: 'assets/icons/lumos.svg' },
    { cat: 'wand', name: 'Flashlight', say: 'пока горит Люмос + «Flashlight» («Флешлайт», «фонарик»)', desc: 'Пока горит Люмос, скажите «Flashlight» — свет станет фонариком. Узкий яркий луч светит туда, куда смотрит палочка, далеко вперёд: это поможет в пещере и ночью. С Люмос Максимой луч ярче и дальше. Повторное слово возвращает обычный свет. Работает только когда Люмос уже горит; погасить — словом «Нокс».', dmg: '—', cost: 3, icon: 'assets/icons/lumos_flashlight.svg' },
    { cat: 'wand', name: 'Ahead', say: 'пока горит Люмос + «Ahead» («Эхед»)', desc: 'Пока горит Люмос, скажите «Ahead» — шарик света сорвётся с палочки и полетит туда, куда она направлена. Поможет осветить далёкое место или заглянуть в темноту: шарик замедляется, мягко отскакивает от стен и гаснет примерно через 15 секунд. Чтобы зажечь палочку снова, скажите «Люмос».', dmg: '—', cost: 3, icon: 'assets/icons/lumos_ahead.svg' },
    { cat: 'wand', name: 'Lumos Following', say: 'поднять палочку + «Lumos Following» («Люмос Фоловинг»)', desc: 'Поднимите палочку и скажите «Lumos Following» («Люмос Фоловинг»). Шарик света отделится от палочки и поплывёт рядом с вами, чуть впереди у плеча, освещая путь, куда бы вы ни шли. На бегу он летит быстрее и забегает вперёд. Не мешает другим заклинаниям. Тратит 0,1 маны в секунду; когда мана кончится, гаснет. Погасить — словом «Нокс».', dmg: '—', cost: 15, icon: 'assets/icons/lumos_following.svg' },
    { cat: 'wand', name: 'Lightning Writing', say: 'палочка в руке + «Лайтнинг Райтинг» (Lightning Writing)', desc: 'Возьмите палочку в руку и скажите «Лайтнинг Райтинг» (Lightning Writing). Теперь палочкой можно рисовать в воздухе: за её кончиком остаются светящиеся линии её цвета. Рисунок держится около 10 секунд, а затем тускнеет. Поможет оставить знак или подсказку для других: их тоже видят все игроки.', dmg: '—', icon: 'assets/icons/light_writing.svg' },
];

